const select = (prompt: L, context: L, items: [string,L,L][], expected: string[]): Class8Task => ({...base(prompt,context),kind:'select',items:items.map(([id,label,feedback])=>({id,label,feedback})),expected});
const match = (prompt:L,context:L,rows:[string,L,string,L][],options:[string,L][]):Class8Task=>({...base(prompt,context),kind:'match',rows:rows.map(([id,label,answer,explanation])=>({id,label,answer,explanation})),options:options.map(([id,label])=>({id,label}))});
const order=(prompt:L,context:L,items:[string,L][],expected:string[]):Class8Task=>({...base(prompt,context),kind:'order',items:items.map(([id,label])=>({id,label})),expected});
